/** 网页地址和宿主权限边界。不允许网页构造本地执行目标。 */
export const INTERNAL_URLS = new Set(['tao://home']);
export function taoSearchUrl(query){const q=String(query??'').trim().slice(0,500);return `tao://search?q=${encodeURIComponent(q)}`;}
export function parseTaoSearchUrl(value){try{const u=new URL(String(value));if(u.protocol!=='tao:'||u.hostname!=='search'||(u.pathname&&u.pathname!=='/')||u.hash)return null;for(const key of u.searchParams.keys())if(key!=='q')return null;const q=(u.searchParams.get('q')||'').trim();if(q.length>500||/[\u0000-\u001f\u007f]/.test(q))return null;return {query:q,url:taoSearchUrl(q)};}catch{return null;}}
export function isInternalUrl(value){return INTERNAL_URLS.has(value)||!!parseTaoSearchUrl(value);}
export const SEARCH_ENGINES = Object.freeze({tao:q=>taoSearchUrl(q),bing:q=>`https://www.bing.com/search?q=${encodeURIComponent(q)}`,google:q=>`https://www.google.com/search?q=${encodeURIComponent(q)}`,duckduckgo:q=>`https://duckduckgo.com/?q=${encodeURIComponent(q)}`});
export function searchUrl(query, engine='tao'){const fn=SEARCH_ENGINES[engine]||SEARCH_ENGINES.tao;return fn(String(query??'').trim());}
export function normalizeAddress(input, engine='tao') {const raw=String(input??'').trim();if(!raw)return 'tao://home';if(raw.length>8192)throw new Error('地址过长');if(/[\u0000-\u001f\u007f]/.test(raw))throw new Error('地址含控制字符');if(isInternalUrl(raw))return parseTaoSearchUrl(raw)?.url||raw;if(/^[a-z][a-z\d+.-]*:/i.test(raw)&&!/^https?:/i.test(raw)&&! /^(localhost|[\d.]+):\d+/i.test(raw))throw new Error('仅允许 HTTP、HTTPS 与 Tao Browser 内置页面；禁止脚本、文件及外部程序协议');if(/\s/.test(raw))return searchUrl(raw,engine);let candidate=raw;if(!/^https?:\/\//i.test(candidate)){if(/^(localhost|127\.0\.0\.1|\[::1\])(?::\d+)?(?:\/|$)/i.test(candidate))candidate='http://'+candidate;else if(/^[^\s/]+\.[^\s/]+/.test(candidate))candidate='https://'+candidate;else return searchUrl(raw,engine);}return validateWebUrl(candidate);}
export function validateWebUrl(value){if(typeof value!=='string'||value.length>8192||/[\u0000-\u001f\u007f]/.test(value))throw new Error('网址字符或长度无效');let u;try{u=new URL(value);}catch{throw new Error('网址格式不正确');}if(!['http:','https:'].includes(u.protocol)||!u.hostname)throw new Error('不允许该网页协议');if(u.username||u.password)throw new Error('地址中不能携带账号或密码');return u.href;}
export function isWebUrl(value){try{validateWebUrl(value);return true;}catch{return false;}}
export function providerEndpoint(value){const u=new URL(validateWebUrl(String(value).trim()));if(u.search||u.hash)throw new Error('模型端点不能含查询参数或片段；密钥请放入专用输入框');if(u.protocol==='http:'&&!['localhost','127.0.0.1','[::1]'].includes(u.hostname))throw new Error('远程模型端点必须使用 HTTPS；HTTP 仅允许本机');return u.href.replace(/\/$/,'');}
export function text(value,max=200){if(typeof value!=='string')throw new Error('需要文本');return value.trim().slice(0,max);}
export function requireTrustedSender(event,shellContents,shellUrl){if(event.sender!==shellContents||event.senderFrame!==shellContents.mainFrame||event.senderFrame?.url!==shellUrl)throw new Error('拒绝非本地浏览器界面的调用');}
export function validateBounds(value,width,height){if(!value||!['x','y','width','height'].every(k=>Number.isFinite(value[k])))throw new Error('页面区域无效');const x=Math.max(0,Math.min(Math.round(value.x),width)),y=Math.max(0,Math.min(Math.round(value.y),height));return {x,y,width:Math.max(0,Math.min(Math.round(value.width),width-x)),height:Math.max(0,Math.min(Math.round(value.height),height-y))};}
